    const cen = [(prof[0][0] + prof[1][0] + prof[2][0] + prof[3][0]) / 4, (yb + yt) / 2];
    const inset = prof.map(([pz2, py2]) => [cen[0] + (pz2 - cen[0]) * 0.86, cen[1] + (py2 - cen[1]) * 0.74 + 0.01]);
