      const seatCols = ["#24262a", "#3a342e", "#2b3038", "#4a4338"];
      const sc = seatCols[Math.floor(rnd() * seatCols.length)];
      const zD = prof[2][0] - 0.3, hipY = 0.56, zW = prof[3][0];
      G2.box(0, 0.5, (prof[0][0] + prof[3][0]) / 2, 2 * cw - 0.1, 0.05, prof[3][0] - prof[0][0] - 0.2, "#25262a");
      G2.box(0, 0.9, zW - 0.28, 2 * cw - 0.12, 0.14, 0.5, "#1d1e21");
      G2.box(0, 0.98, zW - 0.5, 2 * cw - 0.3, 0.07, 0.3, "#17181a");
