  var V32 = (x, y, z) => new Vector3(x, y, z);
  function buildCarModel(ctx, c) {
    const M2 = ctx.M;
    const rnd = mulberry32(c.id.length * 977 + Math.round(c.price));
    const S = new BatchSet();
    const dim = addCar(S, rnd, { type: c.type, sport: !!c.sport, color: c.color, lights: "lampW", people: false, noWheels: true });
    const group = new Group();
    const map = { paint: "paint", glass: "glass", cglass: "carGlass", generic: "generic", lampW: "lampW" };
    for (const [k, b] of Object.entries(S.b)) {
      if (b.empty) continue;
      const m = new Mesh(b.build(), M2[map[k]]);
      m.castShadow = k !== "glass" && k !== "cglass" && k !== "lampW";
      m.receiveShadow = true;
      group.add(m);
    }
    const sport = !!c.sport;
    const Lw = sport ? dim.L / 1.06 : dim.L, Ww = sport ? dim.W / 1.05 : dim.W;
    ensureWheelParts();
    const wheels = [];
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      const WB = new BatchSet();
      addWheel(WB.get("generic"), 0, 0, 0, sx);
      const wx = sx * (Ww / 2 - 0.13) * (sport ? 1.03 : 1), wz = sz * Lw * 0.31;
      const pivot = new Group();
      pivot.position.set(wx, 0.335, wz);
      const spin = new Group();
      pivot.add(spin);
      const mesh = new Mesh(WB.get("generic").build(), M2.generic);
      mesh.castShadow = true;
      spin.add(mesh);
      group.add(pivot);
      wheels.push({ pivot, spin, front: sz > 0 });
    }
    const cab = dim.cab, prof = cab.prof;
    const zD = prof[2][0] - 0.3 * (sport ? 1.06 : 1), wz2 = zD + 0.62 * (sport ? 1.06 : 1);
    const DB = new BatchSet();
    const sc = sport ? 0.8 : 1;
    addSeated(DB.get("generic"), 0.4 * (sport ? 1.05 : 1), 0.56 * sc, zD - 0.1, { wheel: { x: 0.4 * (sport ? 1.05 : 1), y: 0.96 * sc, z: wz2 }, female: false, shirt: "#2f3b4a" }, rnd);
    const driver = new Group();
    for (const [k, b] of Object.entries(DB.b)) {
      if (b.empty) continue;
      const m = new Mesh(b.build(), M2.generic);
      m.castShadow = true;
      driver.add(m);
    }
    driver.visible = false;
    group.add(driver);
    const dummyGlow = new Mesh(new PlaneGeometry(0.1, 0.1), new MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }));
    const v = c.kmh / 3.6;
    const wb = Lw * 0.62;
    const exX = sport ? 0.32 : 0.52 * (Ww > 1.9 ? 1 : 0.9);
    const spec = { vN: v, vT: v, vVN: v, vVT: v, aN: c.a, aT: c.a, aVN: c.a, aVT: c.a, kN: c.knee, kT: c.knee, kVN: c.knee, kVT: c.knee, drag2: c.drag2, brake: c.brake, space: c.brake + 2, cap: c.brake + 3, aLat: c.aLat, mass: 1400, wheelie: 0 };
    const hip = sport ? 0.8 : 1;
    return {
      id: c.id,
      name: c.name,
      group,
      steer: new Group(),
      frontWheel: new Group(),
      rearWheel: new Group(),
      vescParts: [],
      glow: dummyGlow,
      glowSize: [0.1, 0.1],
      paint: { body: [], accent: [] },
      noVesc: true,
      noDecor: true,
      noPaint: true,
      car: true,
      riderDY: 0,
      wheelieBar: new Group(),
      driver,
      exhaust: { stock: V32(sport ? 0.32 : exX, 0.37 * sc, -dim.L / 2 - 0.12), pipes: sport ? [V32(0.42, 0.34, -dim.L / 2 - 0.12), V32(0.22, 0.34, -dim.L / 2 - 0.12), V32(-0.22, 0.34, -dim.L / 2 - 0.12), V32(-0.42, 0.34, -dim.L / 2 - 0.12)] : [V32(exX, 0.37, -dim.L / 2 - 0.12)] },
      gripLocal: [V32(0.3, 1, 0), V32(-0.3, 1, 0)],
      foot: [V32(0.2, 0.2, 0), V32(-0.2, 0.2, 0)],
      half: wb / 2,
      wheelbase: wb,
      wheelR: 0.335,
      spotPos: [0, 0.7, dim.L / 2],
      dispMode: "AUTO",
      fp: { y: 1.22 * (sport ? 0.8 : 1), x: 0.4 * (sport ? 1.05 : 1) * 1, z: zD - 0.05, pitch: 0 },
      colR: Ww * 0.5 + 0.04,
      colOffs: [dim.L * 0.3, 0, -dim.L * 0.3],
      camMul: 1.9 + (dim.H > 1.6 ? 0.3 : 0),
      dismountOff: Ww / 2 + 0.9,
      mountR: 4.6,
      dims: { L: dim.L, W: dim.W, H: dim.H, type: c.type, sport },
      spec,
      update(sc2) {
        for (const w of wheels) {
          w.spin.rotation.x = sc2.wheelAng;
          if (w.front) w.pivot.rotation.y = sc2.delta * 0.9;
        }
      }
    };
  }

