        const a = lo + len * (0.25 + rnd() * 0.5), y = CURB2 + (1 + Math.floor(rnd() * (b.floors - 1))) * FLOOR + 1.5;
        const g = this.dishGeo || (this.dishGeo = new CylinderGeometry(0.3, 0.04, 0.12, 14));
        const m = new Matrix4();
