        at(a, 0.07, CURB2 + 1.15, 1.4, 2.3, 0.14, DOORS[Math.floor(rnd() * DOORS.length)]);
        at(a, 0.55, CURB2 + 2.55, 2, 0.1, 1.2, "#4a4d52");
