    st.crashT = 0.12;
    $("crash").style.opacity = 0.25;
    if (knife) {
      const l = Math.hypot(dx, dz) || 1;
      blood.splash(best.x - dx / l * 0.1, 1.15, best.z - dz / l * 0.1, dx / l, dz / l, r === "ko" ? 26 : 16);
      if (r === "ko") {
        st.score = Math.max(0, st.score - 250);
        best.bloodPool = blood.pool(best.x, best.z, 1.1);
        ems.call(best);
        toast(best.elder ? best.kind === "oma" ? "Oma niedergestochen" : "Opa niedergestochen" : "Niedergestochen", "liegt blutend am Boden \u2013 der Krankenwagen ist unterwegs \xB7 \u2212250 Punkte", 3200);
      }
      return;
    }
    if (r === "ko") {
      koCount++;
      st.score = Math.max(0, st.score - 120);
      toast(best.elder ? best.kind === "oma" ? "Oma K.O.!" : "Opa K.O.!" : "K.O.! \u{1F94A}", "liegt am Boden \u2013 nicht sch\xF6n \u2026 \u2212120 Punkte", 2600);
    }
