      const far = !ch2 || ch2.d > 220;
      if (!(riding && scooter.wheelie > 0.3)) st.wanted -= dt * (far ? 2.5 : 1);
      if (ch2 && ch2.d < 7 && me.speed < 3.5) st.bustT += dt;
